/* ================= jselxday: THE 3 OPENING DAYS of a tú nữ life (SELSCENE-4, review/selection-scene) =================
   Owner rows (verbatim in dev/OWNER_DECISIONS.md, handover branch): 24/11 ~07:05Z (3 playable days = 3 tuần, 16 khắc each, a drama every day),
   ~07:45Z (each day opens with its title card «Ngày … — <name>»), ~08:20Z FINAL (Dưỡng Tú viện: Đông / Tây / Bắc sở, 4 per room, 2 per bed, a shared
   Tiền sảnh where the ma ma teaches; day 1 teaching COSTS khắc) + MAIN 117 plan 08:22Z (DAY 1 «Nhập cung», DAY 2 «Điện tuyển», DAY 3 «Chờ chiếu»);
   ~06:00Z / ~06:20Z (lodging dramas move RELATIONS only, never the score); ~06:15Z (contest of 12, top 4 kept, she outside = ban hoa); row 55 (WHY).
   FLOW (modal cards of the kit, one beat per card; the scene layer KIT §93 / KK17 dresses the same beats later — every beat is a named function):
     D1 selxD1Gate (gate + roll-call: names are called, nobody is MET) → selxD1Rooms (Giáo tập ma ma assigns the sở) → selxLesson (Tiền sảnh drill
        «quy củ», 3 efforts of equal value: more khắc ↔ better regard; result = the ma ma's regard + hints of what the royals value, score untouched)
        → selxFree (free khắc: greet «Người lạ», talk, walk to another sở / Tiền sảnh, rest) → selxEve (evening dorm drama) → night.
     D2 selxD2Dress → selxYard (BAL.selx.beat.yard khắc: greet, Dò hỏi, rest; the yard drama) → selxHall → selxTest T (đối đáp) → Hoàng thượng's
        mini-game (jkc2 kc2Sel card) → selxTest H (hành xử) → selxContestRun (12 scored, kit podium, top 4 kept; she outside = ban hoa = the life ends).
     D3 selxD3Teach (palace rules) → selxFree → selxEve (drama of the 4 kept) → selxEdict (rank ±1 of jselx, Sắc phong news) → the life's «Nhập cung» card.
   LAW 1 (two-way): every tú nữ takes the same lesson (selxLessonMark), lives on the same day plan (selxWhere), takes the same 3 tests (jselx
   selxNpcMarks with the same royal reaction selxReactR), acts in every drama by her nết (selxBystand), may target HER (victim stances SELX_VST).
   ONE CORE: every number = BAL.selx (jbal2.js); the day = B4N buổi × BAL.time.khac khắc. Player text per VANPHONG (number words, no digits, no %).
   New lives only (S.selx2.days); old saves keep their path. Content (dramas, tests) = jselxd.js (generated by dev/build/gen_selxd.py). */
const SELX_DAYN=["Nhập cung","Điện tuyển","Chờ chiếu"];
const SELX_ORD=["nhất","hai","ba"];
function selxDayName(n){return SELX_DAYN[(n|0)-1]||null}
/* KIT §94b day title card hook (MAIN 117, review/kit-daytitle 35221155): the kit shows «Ngày N — <name>» from window.kitDayName(n), null outside the opening */
function kitDayName(n){return selxDayName(n)}
function selxDayTitle(n){return `Ngày thứ ${SELX_ORD[(n|0)-1]||""} — ${selxDayName(n)}`}
function selxDayK(){return B4N*BAL.time.khac}
function selxNumW(n){n=Math.max(0,n|0);const U=["không","một","hai","ba","bốn","năm","sáu","bảy","tám","chín"];if(n<10)return U[n];const c=Math.floor(n/10),u=n%10;
 return (c===1?"mười":U[c]+" mươi")+(u===0?"":u===5?" lăm":u===1&&c>1?" mốt":" "+U[u])}
function selxCap(t){return t?t[0].toUpperCase()+t.slice(1):t}
function selxDaysOn(){return !!(S&&!S.dead&&S.selx2&&S.selx2.days)}
function selxDaysFit(){const k=S&&S.origin&&S.origin.k;return !!k&&k!=="cnv"&&k!=="cn"&&!selxHoaThan(k)}
function selxZ(){return S.selx2}
/* who is who: ids in the save, objects in S.selx2.girls (until the contest) or rivals (the kept, after it) */
function selxBy(id){if(id==="me")return S;const Z=S.selx2;return (Z.girls||[]).find(v=>v.id===id)||(Z.keptV||[]).find(v=>v.id===id)||(rivals||[]).find(v=>v.id===id)||null}
function selxAll(){const Z=S.selx2;return (Z.girls&&Z.girls.length?Z.girls:(Z.keptV||[])).filter(Boolean)}
function selxMet(v){try{return v===S||!!(S.selx2.met||{})[v.id]||k61Named(v)}catch(e){return false}}
function selxNm(v){return v===S?"ngươi":selxMet(v)?v.name:"một tú nữ lạ mặt"}
/* RV-SELX (law 7/11): a LIST of girls names the met ones, then counts the strangers in words (was «một tú nữ lạ mặt, một tú nữ lạ mặt, …») */
function selxNmL(L){const k=L.filter(v=>v===S||selxMet(v)).map(selxNm),n=L.length-k.length;if(n===1)k.push("một tú nữ lạ mặt");else if(n>1)k.push(`${selxNumW(n)} tú nữ lạ mặt`);return k.join(", ")}
function selxMaMa(){try{const m=elderBy("gt");return m?staffFace(m):null}catch(e){return null}}
function selxWho(v){try{return v===S?pMe():pv(v)}catch(e){return null}}
function selxSo(id){const L=(BAL.selx.lodge.so||[]);const x=L.find(s=>s[0]===id);return x?x[1]:id===BAL.selx.lodge.sanh[0]?BAL.selx.lodge.sanh[1]:""}
/* ---- the day clock: Z.kh = khắc left today; the buổi is the khắc spent / BAL.time.khac ---- */
function selxSpend(n){const Z=S.selx2;Z.kh=Math.max(0,(Z.kh==null?selxDayK():Z.kh)-Math.max(0,n|0))}
function selxBuoi(){const Z=S.selx2;return Math.min(B4L,Math.floor((selxDayK()-(Z.kh==null?selxDayK():Z.kh))/BAL.time.khac))}
function selxHead(){const Z=S.selx2;return `<p><small>${selxDayTitle(Z.days)} · ${BUOI[selxBuoi()]} · còn ${selxNumW(Z.kh)} khắc</small></p>`}
function selxEvening(){return S.selx2.kh<=BAL.time.khac}
/* ---- a beat = one kit modal card; the option's go pushes the next beat ---- */
function selxCard(t,h,opts,who){const m={t,h:selxHead()+h,opts,who:who||null,pid:"selxD",pp:{}};Q.unshift(m);return m}
/* every selx option snapshots the ma ma's regard (Z.ma) before it runs, so its result card can show that change (law 3: an act whose gain is the ma ma's regard never reads «không đổi chỉ số») */
let SELX_B=null;
/* the option hint (kit option card rows): k khắc it costs (kit «N khắc» Tốn item, like every act card) + what it gains (law 3: every option gains something) + what may come with it */
function selxX(k,g,kem){return [k>0?`${k} khắc`:"",g?`thành: ${g}`:"",kem?`kèm: ${kem}`:""].filter(Boolean).join(" · ")}
function selxO(n,go,more){return Object.assign({n,fx:{},x:"",go:function(){try{SELX_B={ma:(S.selx2&&S.selx2.ma)||0}}catch(e){SELX_B=null}return go.apply(this,arguments)}},more||{})}
function selxRes(title,b,txt,know){try{if(txt)log(txt)}catch(e){}try{(know||[]).forEach(k=>kitKnow({text:k,key:"selx:"+k}))}catch(e){}
 const dm=SELX_B&&S.selx2?(S.selx2.ma||0)-SELX_B.ma:0;SELX_B=null;
 /* the ma ma's regard is not a stat: when it moved, the kit §93.8 card with given rows shows it in words beside the stat rows (no digits, law 7) */
 if(dm&&!window.__bot&&typeof kitResultCard==="function"&&typeof kaResultRows==="function"){try{const [G,B]=kaResultRows(b,title);const who='<span class="ef t">Giáo tập ma ma:</span> ';
   (dm>0?G:B).push(who+(dm>0?'<span class="ef g">để ý tới ngươi hơn</span>':'<span class="ef r">không vừa ý ngươi</span>'));let sen="";try{sen=kaSentence(b)}catch(e){}
   kitResultCard({title,ok:null,sen,rows:[{k:"duoc",label:"Được",items:G},{k:"mat",label:"Mất",items:B}]});selxResHold();return}catch(e){}}
 try{resultShow(title,b,true)}catch(e){}selxResHold()}
/* ONE card per selx deed: the option wrapper (j19 wrapR «chooseM») would show a second, generic card titled by the option (it reads only stats, so the ma ma's regard read «không đổi chỉ số»
   and covered the selx card); after selxRes the rest of this click shows no other result card (same pattern as jts __tsNoRes) */
let SELX_RES_HOLD=0;function selxResHold(){SELX_RES_HOLD=1;setTimeout(()=>{SELX_RES_HOLD=0},0)}
(function(){if(typeof resultShow!=="function")return;const r0=resultShow;resultShow=function(){if(SELX_RES_HOLD)return;return r0.apply(this,arguments)}})();
/* ---- DAY START (title card, kit day card hook for KK17: window.selxDayName) ---- */
function selxDay(n){const Z=S.selx2;Z.days=n;Z.kh=selxDayK();Z.at=Z.home||(BAL.selx.lodge.so[0][0]);
 if(n===1)return selxD1Gate();if(n===2)return selxD2Dress();return selxD3Teach()}
/* ================= DAY 1 «Nhập cung» ================= */
function selxD1Gate(){const Z=S.selx2;const L=selxAll();Z.heard=L.map(v=>v.id);
 selxCard(selxDayTitle(1),`<p>Trời vừa hửng, xe đưa tú nữ dừng trước cửa Bắc. Thái giám Nội vụ phủ cầm sổ, đọc tên từng người cùng chức tước của cha: ${L.map(v=>v.name).join(", ")}.</p><p>Tên thì nghe cả, nhưng mặt người nào ứng với tên nào, ngươi chưa biết.</p>`,
  [selxO("Theo thái giám vào cửa viện",()=>{selxSpend(BAL.selx.beat.gate);selxD1Rooms()},{x:selxX(BAL.selx.beat.gate,"vào Dưỡng Tú viện, nhận sở ở")})],(()=>{try{return pMsg()}catch(e){return null}})())}
function selxD1Rooms(){const Z=S.selx2;const R=(Z.rooms||[])[0]||{so:BAL.selx.lodge.so[0][0],ids:["me"]};Z.home=R.so;Z.at=R.so;const mates=R.ids.filter(i=>i!=="me").map(selxBy).filter(Boolean);
 selxCard(BAL.selx.lodge.n,`<p>Qua cổng ${BAL.selx.lodge.n}, Giáo tập ma ma đứng chờ, tay cầm thước gỗ. Bà chia mỗi sở một phòng, ${selxNumW(BAL.selx.room.perRoom)} người một phòng, ${selxNumW(BAL.selx.room.perBed)} người một giường.</p><p>Ngươi ở <b>${selxSo(R.so)}</b>, cùng phòng với ${selxNumW(mates.length)} tú nữ ngươi chưa quen. Ma ma dặn: «Cất đồ rồi ra ${BAL.selx.lodge.sanh[1]}, học quy củ.»</p>`,
  [selxO(`Cất đồ, ra ${BAL.selx.lodge.sanh[1]}`,()=>{selxSpend(BAL.selx.beat.rooms);Z.at=BAL.selx.lodge.sanh[0];selxLesson()},{x:selxX(BAL.selx.beat.rooms,"ra học quy củ với ma ma")})],selxMaMa())}
/* the drill: effort i (0 = kỹ, 1 = vừa, 2 = qua loa) costs BAL.selx.lesson.k[i] khắc; mark = the same formula for everyone (law 1) */
function selxLessonMark(p,i){const L=BAL.selx.lesson;const m=L.base+L.duc*(+p.duc||0)+L.eff*(L.k.length-1-i)+R(2*L.r+1)-L.r;return Math.max(0,Math.min(10,Math.round(m)))}
const SELX_LES=[["Tập thật kỹ từng bước, từng lạy","Ngươi tập tới mỏi gối."],["Tập cho thuộc rồi thôi","Ngươi thuộc bài, lễ nghi đã vào nếp."],["Tập qua loa, để sức cho ngày mai","Ngươi ngồi nghỉ ở góc sảnh, sức hồi lại."]];
function selxLesson(){const Z=S.selx2;const L=BAL.selx.lesson;
 selxCard(BAL.selx.lodge.sanh[1],`<p>Ma ma dạy quy củ: đi bước nhỏ, mắt không ngẩng quá vai người trên; hành lễ vạn phúc hai tay chồng bên hông; thưa gửi nhỏ nhẹ, không cướp lời.</p><p>Bà gõ thước: «Ai tập kỹ, ta nhớ. Ai lười, ta cũng nhớ.»</p>`,
  SELX_LES.map(([n,o],i)=>selxO(n,()=>{const b=rsnap();selxSpend(L.k[i]);const mk=selxLessonMark(S,i);Z.lesson=mk;const dm=(mk-L.mid)*BAL.selx.maStep;const dmm=i===0?Math.max(L.maMin*BAL.selx.maStep,dm):dm;Z.ma=(Z.ma||0)+dmm;
   const fx=L.fx[i]||{};if(fx.duc)S.duc=cl((S.duc||0)+fx.duc,0,100);if(fx.suc)S.suc=cl((S.suc||0)+fx.suc,0,sucCap(S));
   selxAll().forEach(v=>{const e=R(L.k.length);v.__ma=(v.__ma||0)+(selxLessonMark(v,e)-L.mid)*BAL.selx.maStep});/* law 1: every girl takes the same lesson */
   try{selxAskNpc()}catch(e){}
   const know=[];const H=selxHints(mk);H.forEach(t=>know.push(t));
   selxRes("Học quy củ",b,`${o} ${dmm>0?"Ma ma gật đầu, để ý tới ngươi.":dmm<0?"Ma ma nhíu mày, không vừa ý ngươi lắm.":"Ma ma không khen không chê."}`,know);Z.at=Z.home;selxFree()},{x:selxLesX(i)})),selxMaMa())}
function selxLesX(i){const L=BAL.selx.lesson;const f=L.fx[i]||{};return selxX(L.k[i],i===0?"Giáo tập ma ma để ý tới ngươi hơn; có khi bà buột miệng điều các vị chí tôn trọng":f.duc?`Đức +${f.duc}`:`Sức +${f.suc}`,i===2?"ma ma không vừa ý ngươi":"")}
/* hints (knowledge only, score untouched): a high mark → the ma ma lets slip what one / two royals value this life */
function selxRoyals(){const q=(()=>{try{return liveRivals(false).find(v=>v.queen)||null}catch(e){return null}})();return [["T","Thái hậu","th"],["E","Hoàng thượng",S.emp],["H","Hoàng hậu",q]].filter(x=>x[2])}
function selxTrong(tok){try{return trongOf(tok)||[]}catch(e){return[]}}
function selxHints(mk){const Z=S.selx2;Z.know=Z.know||{};const n=BAL.selx.lesson.hint.filter(t=>mk>=t).length;const out=[];
 for(const [k,nm,tok] of selxRoyals()){if(out.length>=n)break;if(Z.know[k])continue;const tr=selxTrong(tok);if(!tr.length)continue;Z.know[k]=1;out.push(`Ma ma buột miệng: ${nm} trọng chữ ${tr[0]}.`)}return out}
/* ---- where every girl is now (law 1: the same day plan for all; the 4 kept stay together on day 3) ---- */
function selxHash(s){let h=7;for(const c of String(s))h=(h*31+c.charCodeAt(0))>>>0;return h}
function selxHomeOf(v){const Z=S.selx2;const r=(Z.rooms||[]).find(x=>x.ids.includes(v===S?"me":v.id));return r?r.so:Z.home}
function selxWhere(v){const Z=S.selx2;if(Z.days===3)return v===S?Z.at:Z.home;const W=BAL.selx.roam;const t=W[0]+W[1];return selxHash(v.id+":"+Z.days+":"+selxBuoi())%t<W[1]?BAL.selx.lodge.sanh[0]:selxHomeOf(v)}
function selxHere(){const Z=S.selx2;return selxAll().filter(v=>selxWhere(v)===Z.at)}
/* ---- free khắc (days 1 and 3): greet, talk, walk, rest; at tối the evening drama ---- */
function selxFree(){const Z=S.selx2;if(selxEvening())return selxEve();const H=selxHere();const o=[];const T=BAL.time.cost.talk;
 H.filter(v=>!selxMet(v)).slice(0,BAL.selx.menuN).forEach(v=>o.push(selxO(`Làm quen với ${selxNm(v)}`,()=>{selxSpend(T);selxGreet(v);selxFree()},{x:selxX(T,"biết mặt nàng; nàng chịu thì biết cả tên")})));
 H.filter(v=>selxMet(v)).slice(0,BAL.selx.menuN).forEach(v=>o.push(selxO(`Trò chuyện với ${v.name}`,()=>{const b=rsnap();selxSpend(T);relAdd(S,v,BAL.selx.fx.s);selxRes("Trò chuyện",b,`Ngươi ngồi nói chuyện với ${v.name} một lúc; hai người thân hơn.`);selxFree()},{x:selxX(T,`${v.name} thân với ngươi hơn`)})));
 if(Z.days!==3)[...BAL.selx.lodge.so.map(s=>s[0]),BAL.selx.lodge.sanh[0]].filter(p=>p!==Z.at).forEach(p=>o.push(selxO(`Sang ${selxSo(p)}`,()=>{selxSpend(BAL.walk.near);Z.at=p;selxFree()},{x:selxX(BAL.walk.near,`tới ${selxSo(p)}, gặp người ở đó`)})));
 if(Z.days===1)selxAskOpts(o,()=>selxFree());
 o.push(selxO("Nghỉ một lát",()=>{const b=rsnap();selxSpend(T);S.suc=cl((S.suc||0)+BAL.selx.rest,0,sucCap(S));selxRes("Nghỉ",b,"Ngươi ngả lưng một lát, sức hồi lại.");selxFree()},{x:selxX(T,`Sức +${BAL.selx.rest}`)}));
 o.push(selxO("Ngồi yên chờ tới tối",()=>{Z.kh=Math.min(Z.kh,BAL.time.khac);selxFree()},{x:selxX(0,"tới ngay buổi tối, không phải chờ")}));
 selxCard(selxSo(Z.at),`<p>${H.length?`Ở ${selxSo(Z.at)} lúc này có ${selxNmL(H)}.`:`${selxSo(Z.at)} vắng người.`}</p>`,o,selxMaMa())}
/* greeting = the existing two-way rule (jgreet greetName: a face always, a name only if her nết and birth let her give it) */
function selxGreet(v){const Z=S.selx2;Z.met=Z.met||{};Z.met[v.id]=1;let line="";try{const G=greetName(S,v);line=G&&G.line||""}catch(e){}try{k61Know(v,"Làm quen ở "+BAL.selx.lodge.n,true,1)}catch(e){}
 try{kitKnow({text:`Ngươi biết mặt ${k61Named(v)?v.name:"một tú nữ"}`,key:"selx:met:"+v.id})}catch(e){}if(line)try{log(line)}catch(e){}}
let SELX_CUR=null;
/* ================= DRAMA ENGINE (yard.md Format B: SELX_SEEDS.yard / .dorm / .kept) ================= */
function selxSeen(){try{return JSON.parse(localStorage.getItem("ctm-selx-seen")||"[]")}catch(e){return[]}}
function selxSeenAdd(id){try{const L=selxSeen().filter(x=>x!==id);L.push(id);localStorage.setItem("ctm-selx-seen",JSON.stringify(L.slice(-BAL.selx.drama.mem)))}catch(e){}}
function selxNet(v){try{return (netOf(v)||[]).concat(v.traits||[])}catch(e){return[]}}
function selxFits(v,r){if(!r)return true;const N=selxNet(v);const any=L=>!L||!L.length||L.some(t=>N.includes(t));if(r.birth==="high"&&!((v.r0||0)>=1))return false;if(r.birth==="low"&&(v.r0||0)>=1)return false;return any(r["nết"])&&any(r["lòng"])}
/* cast: the first role-fit girl for each named role (fallback any free girl); bystanders = the rest present (law 6b: real girls only) */
function selxCast(seed,pool){const used=new Set();const cast={};const roles=Object.keys(seed.roles).filter(r=>r!=="bystanders"&&r!=="eunuch");
 for(const r of roles){const L=pool.filter(v=>!used.has(v));const v=L.find(x=>selxFits(x,seed.roles[r]))||L[R(L.length||1)];if(!v)return null;used.add(v);cast[r]=v}
 const B=seed.roles.bystanders||{min:0,max:0};cast.bystanders=pool.filter(v=>!used.has(v)).slice(0,B.max||0);if(cast.bystanders.length<(B.min||0)&&pool.length<(seed.needs&&seed.needs.min_girls||2))return null;return cast}
function selxPick(type,pool){const P=SELX_SEEDS[type]||[];const seen=new Set([...selxSeen(),...(S.selx2.seen||[])]);const L=P.filter(x=>pool.length>=(x.needs&&x.needs.min_girls||2));
 const F=L.filter(x=>!seen.has(x.id));const C=(F.length?F:L).slice();for(let i=C.length-1;i>0;i--){const j=R(i+1);[C[i],C[j]]=[C[j],C[i]]}
 for(const s of C){const c=selxCast(s,pool);if(c)return{s,c}}return null}
function selxFill(t,c,her){return String(t||"").replace(/\{(\w+)\}/g,(m,r)=>{if(r==="bystander")return c.bystanders&&c.bystanders[0]?selxNm(c.bystanders[0]):"một tú nữ";const v=c[r];return v===S||her&&r==="victim"?"ngươi":v?selxNm(v):"một tú nữ"}).replace(/(^|[.!?…]\s+|«\s*)(\p{Ll})/gu,(m,a,b)=>a+b.toUpperCase())/* RV-SELX: a filled name at a sentence start is capitalised */}
/* her own stances when SHE is the victim (law 1: the girls can target her); equal steps, like every seed stance */
/* her own stances when SHE is the victim: words here, the steps in BAL.selx.vst (law 4, RV-SELX: one-core-guard) */
const SELX_VST=(()=>{const W={benh:"Ta đáp thẳng, không để ai đổ oan.",hua:"Ta nhịn, cúi đầu cho qua chuyện.",hoagiai:"Ta xin ma ma phân xử.",ngoai:"Ta cười xòa, coi như chuyện đùa."};const o={};for(const k in W)o[k]=Object.assign({text:W[k]},BAL.selx.vst[k]);return o})();
const SELX_VOUT={benh:"{bully} sững lại; người xung quanh nhìn ngươi khác đi.",hua:"Chuyện qua, nhưng lời bàn tán còn theo ngươi.",hoagiai:"Ma ma nghe cả hai bên, rồi dặn mọi người giữ miệng.",ngoai:"Không ai cười theo; {bully} cũng mất hứng."};
function selxApply(side,c,f,sign){const D=BAL.selx;const Z=S.selx2;const who=k=>k==="bystander"?(c.bystanders||[]):c[k]?[c[k]]:[];let t=0;
 for(const [key,n] of Object.entries(side||{})){const [a,r]=key.split(".");if(a==="friend"||a==="grudge"){if(r==="ma"){Z.ma=(Z.ma||0)+(a==="friend"?1:-1)*n*D.maStep;continue}
   const s=a==="friend"?1:-1;who(r).forEach(v=>{if(v&&v!==S)relAdd(S,v,s*n*f)})}
  else if(a==="duc")S.duc=cl((S.duc||0)+sign*n*D.ducStep,0,100);else if(a==="face")S.danh=cl((S.danh||0)+sign*n*D.faceStep,0,100);/* face in gain = she keeps face (Danh +), in loss = loses face (Danh −); before it always lowered Danh, so a «face» gain was a hidden loss (law 2/3) */else if(a==="time")t+=sign*n;else if(a==="fav"){/* RV-SELX (law 2/3): «fav» = how the three royals (E / T / H) hear of her from the yard; was written to an unread Z.fav0 (a loss that did nothing) */Z.fav=Z.fav||{};["E","T","H"].forEach(x=>{Z.fav[x]=(Z.fav[x]||0)+sign*n*D.fav.plus})}}return t}
/* bystanders act by their nết (the seed's bystander table): defend → closer to the victim, cold to the bully; join → the reverse (law 1, NPC↔NPC) */
function selxBystand(seed,c,f){const T=seed.bystander||{};for(const v of c.bystanders||[]){const N=selxNet(v);const act=["defend","join","silent","ma"].find(k=>(T[k]||[]).some(x=>N.includes(x)))||(R(2)?"silent":"defend");
  if(act==="defend"){if(c.victim&&c.victim!==v)relAdd(v,c.victim,f);if(c.bully&&c.bully!==v)relAdd(v,c.bully,-f)}else if(act==="join"){if(c.bully&&c.bully!==v)relAdd(v,c.bully,f);if(c.victim&&c.victim!==v)relAdd(v,c.victim,-f)}}}
function selxDrama(type,pool,then){const Z=S.selx2;const P=selxPick(type,pool);if(!P)return then();const {s,c}=P;Z.seen=(Z.seen||[]).concat(s.id);selxSeenAdd(s.id);
 const her=!!s.as_victim&&(s.her||[]).includes("victim")&&R(100)<BAL.selx.drama.victim;if(her)c.victim=S;const f=BAL.selx.fx[s.tier]||BAL.selx.fx.m;
 const ST=her?SELX_VST:s.stances;const intro=her?s.as_victim:s.incident&&s.incident.text;SELX_CUR={s,c,her,type,intro:selxFill(intro,c,her)};/* the scene layer (jselxsc) reads the cast — NOT in the save (the cast holds S) */
 selxCard(type==="yard"?"Sân chờ":selxSo(Z.at)||BAL.selx.lodge.n,`<p>${selxFill(intro,c,her)}</p>`,["benh","hua","hoagiai","ngoai"].map(k=>selxO(selxFill(ST[k].text,c,her),()=>{const b=rsnap();
   let t=BAL.selx.drama.k;t-=selxApply(ST[k].gain,c,f,1);t+=Math.max(0,-selxApply(ST[k].loss,c,f,-1));selxSpend(Math.max(0,t));selxBystand(s,c,f);
   const know=(s.know||[]).map(r=>c[r]).filter(v=>v&&v!==S);know.forEach(v=>{try{k61Know(v,"Cùng một chuyện ở "+(type==="yard"?"sân chờ":BAL.selx.lodge.n),true,1)}catch(e){}});
   const out=selxFill(her?SELX_VOUT[k]:s.outcomes[k],c,her);const mm=s.outcomes&&s.outcomes.maMa;selxRes("Chuyện "+(type==="yard"?"ở sân chờ":"trong viện"),b,`${out}${mm?` Ma ma: «${mm}»`:""}`);then()},{x:selxStX(ST[k],c,her)})),selxWho(c.bully||c.victim))}
/* a stance's option hint: its khắc (drama.k ± the seed's time steps) + its gains / what comes with it, in words with the cast's names (law 2: every stance shows what it is worth) */
function selxStX(st,c,her){const D=BAL.selx;const nm=r=>r==="ma"?"Giáo tập ma ma":r==="bystander"?"người đứng xem":c[r]===S||her&&r==="victim"?"":c[r]?selxNm(c[r]):"";
 const w=(key,n,gain)=>{const [a,r]=key.split(".");if(a==="friend"||a==="grudge"){const who=nm(r);if(!who)return"";return `${who} ${a==="friend"?"quý ngươi hơn":"ghét ngươi hơn"}`}
  if(a==="duc")return `Đức ${gain?"+":"-"}${n*D.ducStep}`;if(a==="face")return `Danh ${gain?"+":"-"}${n*D.faceStep}`;if(a==="fav")return gain?"bề trên để mắt tới":"bề trên kém để mắt";return""};
 let t=D.drama.k;const G=[],K=[];for(const [key,n] of Object.entries(st.gain||{})){if(key==="time"){t-=n;continue}const x=w(key,n,true);if(x)(/ghét|^Danh -|^Đức -/.test(x)?K:G).push(x)}
 for(const [key,n] of Object.entries(st.loss||{})){if(key==="time"){t+=n;continue}const x=w(key,n,false);if(x)(/quý ngươi/.test(x)?G:K).push(x)}
 if(!G.length&&t<D.drama.k)G.push("đỡ tốn khắc");return selxX(Math.max(0,t),G.join("; "),K.join("; "))}
/* the evening: day 1 = a dorm drama among her room and the girls near; day 3 = a drama among the 4 kept; then the night */
function selxEve(){const Z=S.selx2;const d=Z.days;const pool=d===3?selxAll():selxAll().filter(v=>selxHomeOf(v)===Z.home).concat(selxAll().filter(v=>selxHomeOf(v)!==Z.home).slice(0,BAL.selx.drama.extra));
 selxDrama(d===3?"kept":"dorm",pool,()=>d===3&&!S.selx2.two&&R(100)<BAL.selx.drama.two?(S.selx2.two=1,selxDrama("kept",pool,()=>selxNight())):selxNight())}
function selxNight(){const Z=S.selx2;const d=Z.days;if(d===3)return selxEdict();
 selxCard("Đêm",`<p>${d===1?"Đèn tắt. Ngươi nằm nghe tiếng thở của người nằm cạnh, nghĩ tới ngày mai ra điện.":"Đèn tắt. Trong viện chỉ còn ${selxNumW(BAL.selx.yard.kept)} người được ban hương nang."}</p>`,[selxO("Ngủ",()=>selxDay(d+1))])}
/* ================= DAY 2 «Điện tuyển» ================= */
/* ---- DAY 2 morning: the TOILETTE (OD 24/11 ~08:55Z; the existing jtoil mirror, the occasion «Điện tuyển»), or dress as given with a bare face ---- */
function selxD2Dress(){const Z=S.selx2;const I=BAL.selx.imp;const o=[];
 o.push(selxO("Ngồi trước gương điểm trang",()=>{selxSpend(I.dressK);selxToil()},{x:selxX(I.dressK,"tự chọn phấn son, y phục ra mắt ba vị")}));
 o.push(selxO("Theo ma ma ra sân chờ, để mặt mộc",()=>{selxSpend(I.mocK);try{if(S.toilette&&S.toilette.wk===toilWk())S.toilette=null}catch(e){}selxD2Go()},{x:selxX(I.mocK,"ra sân sớm, còn nhiều khắc làm quen ở sân chờ")}));
 /* SELSCENE-8 (RV-SELX FAIL 4): the two roads are of equal value (law 2); the one that opens no board (mặt mộc) stands first, so a card driven
    by its first option alone (the go-live smoke, a bot) passes the day the same way a player who picks it does */
 o.unshift(o.splice(1,1)[0]);selxAskOpts(o,()=>selxD2Dress());
 selxCard(selxDayTitle(2),`<p>Canh tư ma ma đã gõ cửa. Tú nữ thay xiêm y, chải tóc, để ma ma xem lại từng người trước khi ra sân chờ.</p><p>Hôm nay ba vị chí tôn sẽ nhìn mặt từng người: ăn vận, son phấn đều lọt vào mắt các vị.</p>`,o,selxMaMa())}
/* the mirror = jtoil toilOpen (one rule for the look); the day's occasion is the hall (toilOcc wrapper below); when the mirror closes the day goes on */
function selxToil(){const Z=S.selx2;Z.tw=1;let ok=false;try{toilOpen();ok=!!(TOIL&&TOIL.st)||!!toilToday(S)}catch(e){console.error("selx toil",e)}
 if(!ok||toilToday(S)){Z.tw=0;selxD2Go()}}
function selxD2Go(){const Z=S.selx2;Z.yk=BAL.selx.beat.yard;Z.at="san";selxLookSeen();selxYard()}
/* the girls (and the ma ma) see each look in the yard: the one jtoil rule toilSeeRule (frugal praise / frown, mockery, jealousy) → thiện cảm, both ways (law 1) */
function selxLookOf(p){try{return p===S?toilLook():toilLookP(p)}catch(e){return null}}
function selxLookSeen(){const Z=S.selx2;if(Z.lookSeen)return;Z.lookSeen=1;const A=[S,...selxAll()];
 for(const v of selxAll())for(const w of A){if(w===v)continue;let e=null;try{const L=selxLookOf(w);e=L?toilSeeRule(v,L):null}catch(x){}if(e&&e.aff)try{relAdd(v,w,e.aff)}catch(x){}}
 try{const m=elderBy("gt");const L=selxLookOf(S);const R0=BAL.toil.react[toilHostKind(m)]||BAL.toil.react.normal;if(L)Z.ma=(Z.ma||0)+Math.sign((R0[L.dv]||0)+(R0[L.mk]||0))*BAL.selx.maStep}catch(e){}}
/* FIRST IMPRESSION of one royal on one girl (her included, law 1): the jtoil react table of HIS / HER taste on the dress verdict + the face level;
   a girl who learnt this royal's taste from the ma ma (level 2) dresses to fit it */
function selxImpOf(p,k){const ry=selxRoyals().find(x=>x[0]===k);if(!ry)return null;const host=ry[2]==="th"?"th":ry[2]===S.emp?"emp":ry[2];const I=BAL.selx.imp;
 let rec=null,dv="hoppham",mk="moc";try{if(p===S){rec=toilToday(S);dv=toilDress(S,I.F).v}else{rec=toilNpc(p);dv=rec.dv}mk=toilMk(rec)}catch(e){}
 let hk="normal";try{hk=toilHostKind(host)}catch(e){}const T=BAL.toil.react[hk]||BAL.toil.react.normal,C=BAL.toil.cap;
 if(p!==S&&((p.__kn||{})[k]||0)>=2){const best=Object.keys(T).filter(x=>["hopdip","hoppham","giandi","photruong"].includes(x)).sort((a,b)=>T[b]-T[a])[0];if(best)dv=best}
 const a1=T[dv]||0,a2=T[mk]||0;const aff=Math.max(C[0],Math.min(C[1],a1+a2));const mark=Math.max(0,Math.min(10,Math.round(I.mid+I.k*aff)));
 return{k,nm:ry[1],hk,dv,mk,a1,a2,aff,mark}}
function selxImpAll(p){const L=["E","T","H"].map(k=>selxImpOf(p,k)).filter(Boolean);const mk=L.length?Math.round(L.reduce((a,x)=>a+x.mark,0)/L.length):BAL.selx.imp.mid;return{L,mk}}
/* the words of a first impression (WHY, row 55): «Thái hậu chuộng giản dị: y phục hợp dịp, dung nhan đoan trang → ưng ý» */
function selxImpWhy(x){const hk=(typeof TOIL_HK==="object"&&TOIL_HK[x.hk])||"";const dv=(typeof TOIL_DV==="object"&&TOIL_DV[x.dv])||x.dv;let mk="";try{mk=toilMkW(x.mk)}catch(e){mk=x.mk}
 return `${x.nm}${hk?" "+hk:""}: y phục ${dv}, dung nhan ${mk} → ${x.aff>0?"ưng ý, thiện cảm tăng":x.aff<0?"phật ý, thiện cảm giảm":"không để tâm"}.`}
/* the hall sees every girl's look once (her + the 11, the same rule): marks for the score, thiện cảm with each royal (S.selx2.fav / v.__fav) */
function selxImpRun(){const Z=S.selx2;if(Z.impDone)return null;Z.impDone=1;const me=selxImpAll(S);Z.mk=Object.assign(Z.mk||{},{imp:me.mk});Z.imp=me.L.map(x=>({k:x.k,aff:x.aff}));
 Z.fav=Z.fav||{};me.L.forEach(x=>{Z.fav[x.k]=(Z.fav[x.k]||0)+x.aff;if(x.k==="H"){const q=(selxRoyals().find(y=>y[0]==="H")||[])[2];if(q&&typeof q==="object")try{relAdd(S,q,x.aff)}catch(e){}}});
 for(const v of selxAll()){const r=selxImpAll(v);v.__impMk=r.mk;v.__fav=v.__fav||{};r.L.forEach(x=>{v.__fav[x.k]=(v.__fav[x.k]||0)+x.aff})}return me}
/* ---- «DÒ HỎI MA MA» (OD ~09:25Z / ~09:40Z): three roads of equal value (law 2) — pay bạc (sure), win her favour (answer grows with her regard), just ask (free, by her nết) ---- */
function selxAskLvl(mode,ma){const A=BAL.selx.ask;if(mode==="bac")return 2;let m=null;try{m=elderBy("gt")}catch(e){}const N=m?selxNet(m):[];
 let l=mode==="please"?(ma>=A.maHi?2:ma>=0?1:0):(N.some(t=>A.net.full.includes(t))?2:N.some(t=>A.net.one.includes(t))?1:N.some(t=>A.net.no.includes(t))?0:1)-(N.some(t=>A.lure.includes(t))?1:0);
 if(mode==="ask"){if(ma>=A.maHi)l++;else if(ma<=A.maLo)l--}return Math.max(0,Math.min(2,l))}
/* what she learns: level 2 = the royal's taste in dress + both chữ trọng; 1 = one chữ trọng; 0 = nothing */
function selxAskTell(k,lvl){const Z=S.selx2;const ry=selxRoyals().find(x=>x[0]===k);if(!ry)return[];const [kk,nm,tok]=ry;const tr=selxTrong(tok);const out=[];Z.know=Z.know||{};Z.knowT=Z.knowT||{};
 if(lvl>=1&&tr.length){Z.know[kk]=1;out.push(lvl>=2?`Ma ma kể: ${nm} trọng chữ ${tr.join(" và chữ ")}.`:`Ma ma chỉ nói một ý: ${nm} trọng chữ ${tr[0]}.`)}
 if(lvl>=2){Z.knowT[kk]=1;let hk="normal";try{hk=toilHostKind(tok==="th"?"th":tok===S.emp?"emp":tok)}catch(e){}const w=(typeof TOIL_HK==="object"&&TOIL_HK[hk])||"";
  out.push(w?`Ma ma dặn: ${nm} ${w}, ăn vận ra mắt phải liệu cho hợp.`:`Ma ma dặn: ${nm} không khắt khe chuyện y phục, chỉ cần đúng phép.`)}return out}
function selxAskOpts(o,back){const Z=S.selx2;if(Z.days>2)return;const L=selxRoyals().filter(x=>!(Z.know||{})[x[0]]||!(Z.knowT||{})[x[0]]);if(!L.length)return;
 o.push(selxO("Dò hỏi ma ma về các vị chí tôn",()=>selxAsk(back)))}
function selxAsk(back){const Z=S.selx2;const A=BAL.selx.ask;const L=selxRoyals().filter(x=>!(Z.know||{})[x[0]]||!(Z.knowT||{})[x[0]]);const o=[];
 for(const [k,nm] of L){o.push(selxO(`Hỏi về ${nm}`,()=>selxAskHow(k,nm,back)))}o.push(selxO("Thôi, không hỏi nữa",()=>back()));
 selxCard("Dò hỏi ma ma",`<p>Giáo tập ma ma ở trong cung đã lâu, biết rõ tính các vị chí tôn. Ngươi muốn hỏi về vị nào?</p>`,o,selxMaMa())}
function selxAskHow(k,nm,back){const Z=S.selx2;const A=BAL.selx.ask;const T=BAL.time.cost.talk;const o=[];
 const done=(mode,lvl,txt)=>{const b=rsnap();const know=selxAskTell(k,lvl);Z.asked=(Z.asked||0)+1;selxRes("Dò hỏi ma ma",b,lvl?txt:"Ma ma lắc đầu: «Chuyện bề trên, nô tì không dám nói bừa.»",know);back()};
 if((S.bac||0)>=A.bac)o.push(selxO("Dúi bạc vào tay ma ma",()=>{S.bac=Math.max(0,(S.bac||0)-A.bac);selxSpend(T);done("bac",2,"Ma ma cất bạc vào tay áo, ghé tai nói nhỏ.")},{x:`${T} khắc · Bạc -${A.bac} · thành: ma ma kể đủ ${nm} ưa gì, trọng gì`}));
 o.push(selxO("Giúp ma ma việc vặt cho bà vui lòng rồi mới hỏi",()=>{selxSpend(A.pleaseK);Z.ma=(Z.ma||0)+A.maPlease;done("please",selxAskLvl("please",Z.ma),"Ma ma vui lòng, kể cho ngươi nghe.")},{x:selxX(A.pleaseK,"ma ma vui lòng ngươi; bà kể nhiều hay ít tùy lòng bà")}));
 o.push(selxO("Cứ hỏi thẳng",()=>{selxSpend(T);done("ask",selxAskLvl("ask",Z.ma||0),"Ma ma ngẫm một lúc rồi đáp.")},{x:selxX(T,"ma ma đáp tùy tính bà: kể đủ, nói một ý, hoặc lắc đầu")}));
 selxCard("Dò hỏi ma ma",`<p>Ngươi muốn biết ${nm} ưa gì, trọng gì.</p>`,o,selxMaMa())}
/* law 1: every tú nữ may ask the same ma ma on day 1 — a girl of standing pays, a girl of the pleasing nết wins her first, the others just ask (same levels) */
function selxAskNpc(){const A=BAL.selx.ask;const RY=selxRoyals();if(!RY.length)return;for(const v of selxAll()){if(v.__kn)continue;v.__kn={};const k=RY[selxHash(v.id+":ask")%RY.length][0];const N=selxNet(v);
  const mode=(v.r0||0)>=A.npcBuyR0?"bac":N.some(t=>A.npcPlease.includes(t))?"please":"ask";const ma=(v.__ma||0)+(mode==="please"?A.maPlease:0);if(mode==="please")v.__ma=ma;v.__kn[k]=selxAskLvl(mode,ma)}}
function selxYard(){const Z=S.selx2;if(Z.yk<=0)return selxHall();const T=BAL.time.cost.talk;const step=n=>{selxSpend(n);Z.yk-=n};
 if(!Z.yd&&Z.yk<=BAL.selx.beat.yard-BAL.selx.beat.yardDrama){Z.yd=1;return selxDrama("yard",selxAll(),()=>{Z.yk=Math.max(0,Z.yk-BAL.selx.drama.k);selxYard()})}
 const o=[];selxAll().filter(v=>!selxMet(v)).slice(0,BAL.selx.menuN).forEach(v=>o.push(selxO(`Làm quen với ${selxNm(v)}`,()=>{step(T);selxGreet(v);selxYard()},{x:selxX(T,"biết mặt nàng; nàng chịu thì biết cả tên")})));
 const unk=selxRoyals().filter(x=>!(Z.know||{})[x[0]]);if(unk.length)o.push(selxO("Dò hỏi thái giám về các vị chí tôn",()=>{const b=rsnap();step(T);const [k,nm,tok]=unk[0];Z.know=Z.know||{};Z.know[k]=1;const tr=selxTrong(tok);
  selxRes("Dò hỏi",b,"",tr.length?[`Thái giám nói nhỏ: ${nm} trọng chữ ${tr[0]}.`]:[]);selxYard()},{x:selxX(T,"biết một vị chí tôn trọng chữ gì")}));
 o.push(selxO("Đứng yên giữ sức",()=>{const b=rsnap();step(T);S.suc=cl((S.suc||0)+BAL.selx.rest,0,sucCap(S));selxRes("Giữ sức",b,"Ngươi đứng yên dưới bóng hòe, sức hồi lại.");selxYard()},{x:selxX(T,`Sức +${BAL.selx.rest}`)}));
 selxCard("Sân chờ",`<p>${selxCap(selxNumW(BAL.selx.yard.n))} tú nữ đứng chờ dưới tán hòe, chưa ai được gọi. Người thì thầm, người lặng lẽ chỉnh lại trâm cài.</p>`,o)}
function selxHall(){selxCard("Điện tuyển",`<p>Thái giám xướng: «Tú nữ vào điện!» Ngươi theo hàng bước vào, mắt nhìn xuống nền gạch.</p><p>Người ngồi giữa hẳn là Hoàng thượng; bên trái là Thái hậu; bên phải, một vị nương nương đoan trang, hẳn là Hoàng hậu.</p>`,
  [selxO("Quỳ xuống thỉnh an",()=>{selxSpend(BAL.selx.beat.test);const b=rsnap();const me=selxImpRun();if(me&&me.L.length)selxRes("Ba vị nhìn mặt",b,me.L.map(selxImpWhy).join(" "));selxTest("T","doidap",()=>selxMini())},{x:selxX(BAL.selx.beat.test,"ba vị nhìn mặt ngươi lần đầu")})])}
/* the royal's reaction (the same for her and every girl, law 1): an answer that shows a virtue this royal values = "+", one that clashes = "−" */
function selxReactR(opt,tok){const tr=selxTrong(tok);const V=opt&&opt.values||[];if(V.some(x=>tr.includes(x)))return"+";const C=BAL.selx.conf;if(V.length&&tr.some(t=>C.some(([a,b])=>a===V[0]&&b===t||b===V[0]&&a===t)))return"−";return""}
